        if not isinstance(key, (str, int)):
            return (0, 0, 0, 0)
        if isinstance(key, int):
            has_int_key = True
        else:
            if key.lower() != key and key.upper() != key:
                return (0, 0, 0, 0)
            if key == key.lower():
                count_lower += 1
            elif key == key.upper():
                count_upper += 1
            sum_str_len += len(key)

    total_keys = len(dict_input)
    lower_case_ratio = count_lower / total_keys
    upper_case_ratio = count_upper / total_keys
    avg_key_length = sum_str_len / total_keys if total_keys else 0.0

