    if not numbers:
        return []

    # Count occurrences of each number
    count_map = {}
    for num in numbers:
        count_map[num] = count_map.get(num, 0) + 1

    # Helper function to check if a number is digit-balanced
    def is_balanced(num):
        if num < 0:
            num = -num

        running_sum = 0

        # Process each digit
        while num > 0:
            digit = num % 10
            if digit % 2 == 0:  # Even digit
                running_sum += 1
            else:  # Odd digit
                running_sum -= 1

            # Check if running sum goes negative
            if running_sum < 0:
                return False

            num //= 10

        # Final sum should equal zero
        return running_sum == 0

    result = []
    for num in numbers:
        # Check if number appears exactly once and is digit-balanced
        if count_map[num] == 1 and is_balanced(num):
            result.append(num)

    return result

