from typing import List

def remove_balanced_duplicates(numbers: List[int]) -> List[int]:
    # :param numbers: List[int] - A list of integers to process.
    # :return: List[int] - A list of integers after removing duplicates and balancing even and odd numbers.
    # The function removes all numbers appearing more than once. Then, it iterates through the remaining unique numbers,
    # maintaining a balance counter (incremented by 1 for even numbers and decremented by 1 for odd numbers). 
    # Only numbers that keep the balance non-negative are included in the result.
    # Examples:
    # >>> remove_balanced_duplicates([])
    # []
    # >>> remove_balanced_duplicates([1, 2, 3, 4])
    # [2, 4]
    # >>> remove_balanced_duplicates([1, 2, 3, 2, 4])
    # []
    # >>> remove_balanced_duplicates([1, 2, 3, 2, 4, 3, 5])
    # [4]
    unique_numbers = []
    count = {}
    for num in numbers:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    for num in numbers:
        if count[num] == 1:
            unique_numbers.append(num)

    balance = 0
    result = []
    for num in unique_numbers:
        if num % 2 == 0:
            balance += 1
        else:
            balance -= 1

        if balance >= 0:
            result.append(num)
        else:
            # Don't clear the entire result, just skip this number
            # Undo the balance change since we're not including this number
            if num % 2 == 0:
                balance -= 1
            else:
                balance += 1

    return result


