import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def bfs(start):
        queue = deque([(start, [grid[start[0]][start[1]]])])
        visited = set()
        min_path = [float('inf')] * k

        while queue:
            (x, y), path = queue.popleft()
            if len(path) == k:
                if path < min_path:
                    min_path = path[:]
                continue
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited:
                    new_path = path + [grid[nx][ny]]
                    if len(new_path) <= k:
                        queue.append(((nx, ny), new_path))
                        visited.add((nx, ny))
        return min_path

    def find_min_path():
        min_path = [float('inf')] * k
        for i in range(N):
            for j in range(N):
                path = bfs((i, j))
                if path < min_path:
                    min_path = path
        return min_path

    return find_min_path()

