def minPath(grid, k):
    n = len(grid)

    # Find all cells and their positions
    cell_positions = {}
    for i in range(n):
        for j in range(n):
            cell_positions[grid[i][j]] = (i, j)

    # Dynamic programming with memoization
    memo = {}

    def get_neighbors(i, j):
        neighbors = []
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                neighbors.append(grid[ni][nj])
        return neighbors

    def dp(pos_i, pos_j, remaining_steps, current_path):
        if remaining_steps == 0:
            return current_path[:]

        state = (pos_i, pos_j, remaining_steps, tuple(current_path))
        if state in memo:
            return memo[state]

        neighbors = get_neighbors(pos_i, pos_j)
        current_value = grid[pos_i][pos_j]

        # Apply threshold constraint: only consider neighbors below current value + n
        threshold = current_value + n
        valid_neighbors = []
        for neighbor in neighbors:
            if neighbor < threshold:
                valid_neighbors.append(neighbor)

        # If no valid neighbors below threshold, use all neighbors
        if not valid_neighbors:
            valid_neighbors = neighbors

        best_path = None

        # Try staying at current position
        new_path = current_path + [current_value]
        candidate = dp(pos_i, pos_j, remaining_steps - 1, new_path)
        if best_path is None or candidate < best_path:
            best_path = candidate

        # Try moving to each valid neighbor
        for neighbor_val in valid_neighbors:
            neighbor_pos = cell_positions[neighbor_val]
            new_path = current_path + [neighbor_val]
            candidate = dp(neighbor_pos[0], neighbor_pos[1], remaining_steps - 1, new_path)
            if candidate < best_path:
                best_path = candidate

        memo[state] = best_path
        return best_path

    # Find globally optimal path starting from any position
    global_best = None

    # Prioritize starting positions with smaller values
    start_candidates = sorted(range(1, min(n*n + 1, 10)))

    for start_val in start_candidates:
        if start_val in cell_positions:
            start_pos = cell_positions[start_val]
            path = dp(start_pos[0], start_pos[1], k, [])
            if global_best is None or path < global_best:
                global_best = path

    return global_best

