from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    # Find the starting cell with the minimum value
    min_val = min(val for row in grid for val in row)
    start_i, start_j = None, None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == min_val:
                start_i, start_j = i, j
                break
        if start_i is not None:
            break
    path = [min_val]
    current_i, current_j = start_i, start_j
    for _ in range(k-1):
        current_val = grid[current_i][current_j]
        next_positions = [(current_i, current_j)]
        # Generate all possible positions including adjacent cells
        if current_i > 0:
            next_positions.append((current_i -1, current_j))
        if current_i < n -1:
            next_positions.append((current_i +1, current_j))
        if current_j > 0:
            next_positions.append((current_i, current_j -1))
        if current_j < n -1:
            next_positions.append((current_i, current_j +1))
        # Determine allowed positions based on the value condition
        allowed = []
        for i, j in next_positions:
            if grid[i][j] < current_val + n:
                allowed.append((i, j))
        candidates = allowed if allowed else next_positions
        # Find the candidate with the smallest value
        min_next_val = None
        min_next_pos = None
        for i, j in candidates:
            val = grid[i][j]
            if min_next_val is None or val < min_next_val:
                min_next_val = val
                min_next_pos = (i, j)
        path.append(min_next_val)
        current_i, current_j = min_next_pos
    return path

