from typing import List
from collections import deque

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    min_val = float('inf')
    start_i, start_j = 0, 0

    # Find the cell with minimum value
    for i in range(n):
        for j in range(n):
            if grid[i][j] < min_val:
                min_val = grid[i][j]
                start_i, start_j = i, j

    if k == 1:
        return [min_val]

    # Use BFS with priority on lexicographically smallest path
    queue = deque([(start_i, start_j, 1, [min_val])])
    visited = set([(start_i, start_j, 1)])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    best_path = None

    while queue:
        row, col, length, path = queue.popleft()

        if length == k:
            if not best_path or path < best_path:
                best_path = path
            continue

        # Try staying in place
        if length < k:
            new_path = path + [grid[row][col]]
            if (row, col, length + 1) not in visited:
                queue.append((row, col, length + 1, new_path))
                visited.add((row, col, length + 1))

        # Collect valid moves
        valid_moves = []
        curr_val = grid[row][col]
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n:
                next_val = grid[new_row][new_col]
                if next_val < curr_val + n:
                    valid_moves.append((next_val, new_row, new_col))

        # If no valid moves, try any adjacent cell
        if not valid_moves:
            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < n and 0 <= new_col < n:
                    next_val = grid[new_row][new_col]
                    valid_moves.append((next_val, new_row, new_col))

        # Sort moves by value for lexicographically smallest path
        valid_moves.sort()

        for _, new_row, new_col in valid_moves:
            new_path = path + [grid[new_row][new_col]]
            if (new_row, new_col, length + 1) not in visited:
                queue.append((new_row, new_col, length + 1, new_path))
                visited.add((new_row, new_col, length + 1))

    return best_path if best_path else [min_val] * k

