def optimizedPath(grid: List[List[int]], k: int) -> List[int]:
    if not grid or not grid[0]:
        return [-1]

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(row, col, path_length, visited):
        if path_length == k:
            return [grid[row][col]]

        best_path = None

        # Get all valid neighbors
        neighbors = []
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if (0 <= new_row < rows and 0 <= new_col < cols and 
                (new_row, new_col) not in visited and
                grid[new_row][new_col] <= k):
                neighbors.append((new_row, new_col))

        # Sort neighbors by value in descending order to try highest values first
        neighbors.sort(key=lambda x: grid[x[0]][x[1]], reverse=True)

        for new_row, new_col in neighbors:
            visited.add((new_row, new_col))
            sub_path = dfs(new_row, new_col, path_length + 1, visited)
            visited.remove((new_row, new_col))

            if sub_path:
                current_path = [grid[row][col]] + sub_path
                if best_path is None or current_path > best_path:
                    best_path = current_path

        return best_path

    # Find all valid starting positions (cells with value <= k)
    valid_starts = []
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] <= k:
                valid_starts.append((i, j))

    if not valid_starts:
        return [-1]

    # Sort starting positions by value in descending order
    valid_starts.sort(key=lambda x: grid[x[0]][x[1]], reverse=True)

    # Try DFS from each valid starting position
    best_path = None

    for start_row, start_col in valid_starts:
        visited = {(start_row, start_col)}
        path = dfs(start_row, start_col, 1, visited)

        if path and (best_path is None or path > best_path):
            best_path = path

    return best_path if best_path else [-1]

