def optimizedPath(grid: List[List[int]], k: int) -> List[int]:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    if rows == 0 or cols == 0:
        return [-1]

    dp = [{} for _ in range(k)]
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] <= k:
                dp[0][(i, j)] = [grid[i][j]]

    for t in range(k-1):
        current = dp[t]
        next_dp = dp[t+1]
        for (i, j) in current:
            current_path = current[(i, j)]
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + dx, j + dy
                if 0 <= ni < rows and 0 <= nj < cols:
                    val = grid[ni][nj]
                    if val > k:
                        continue
                    new_path = [val] + current_path
                    if (ni, nj) not in next_dp or new_path > next_dp.get((ni, nj), []):
                        next_dp[(ni, nj)] = new_path

    candidates = dp[k-1].values()
    return max(candidates) if candidates else [-1]

