from typing import List

def optimizedPath(grid: List[List[int]], k: int) -> List[int]:
    # Given a grid of integers, find a path of exactly length k such that the maximum value in the path does not exceed k.
    # Moves can only be made to adjacent cells (cells sharing an edge).
    # Return the reversed lexicographically maximum path meeting the constraint, or [-1] if no valid path exists.
    from collections import deque

    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # If k is 0, no path is possible
    if k == 0:
        return [-1]

    # Filter cells that are <= k
    valid_cells = [(i, j) for i in range(m) for j in range(n) if grid[i][j] <= k]
    if not valid_cells:
        return [-1]

    # dp cache: key (i, j, length_left) -> path as List[int] or None if no path
    # The path stored is the reversed lex max path ending at (i,j) of given length
    dp = {}

    # Initialize dp for length 1
    for i in range(m):
        for j in range(n):
            if grid[i][j] <= k:
                dp[(i, j, 1)] = [grid[i][j]]

    for length in range(2, k + 1):
        new_dp = {}
        for i1 in range(m):
            for j1 in range(n):
                if grid[i1][j1] > k:
                    continue
                candidates_paths = []
                for dx, dy in directions:
                    x, y = i1 + dx, j1 + dy
                    if 0 <= x < m and 0 <= y < n and (x, y, length - 1) in dp:
                        prev_path = dp[(x, y, length - 1)]
                        max_val = max(prev_path + [grid[i1][j1]])
                        if max_val <= k:
                            # New candidate path is current cell value plus prev path
                            # This maintains reversed path order
                            candidate = [grid[i1][j1]] + prev_path
                            candidates_paths.append(candidate)
                if candidates_paths:
                    # select lex max path
                    best_path = max(candidates_paths)
                    new_dp[(i1, j1, length)] = best_path
        dp = new_dp
        if not dp:
            break

    # If no dp paths for length k, return [-1]
    final_paths = [path for key, path in dp.items() if key[2] == k]
    if not final_paths:
        # Possible k larger than max reachable length; check if longest path less than k exists?
        # Here problem states path must be exactly length k, so return [-1]
        return [-1]

    # Return lex max reversed path of length k
    return max(final_paths)

