from typing import List

def is_prime(num: int) -> bool:
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def next_prime(num: int) -> int:
    """Find the next prime number."""
    num += 1
    while not is_prime(num):
        num += 1
    return num

def fibonacci(n: int) -> int:
    """Generate Fibonacci sequence up to n."""
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        while b < n:
            a, b = b, a + b
        return b

def next_fibonacci(num: int) -> int:
    """Find the next Fibonacci number."""
    a, b = 0, 1
    while b <= num:
        a, b = b, a + b
    return b

def make_a_pile(n: int) -> List[int]:
    """Create a pile of n levels of stones with advanced rules."""
    pile = [n]
    for _ in range(n - 1):
        if pile[-1] % 2 == 0:
            pile.append(next_fibonacci(pile[-1]))
        else:
