def get_closest_vowel(word: str) -> str:
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}

    # Step 1: Find vowels that are part of a CVC sequence (consonant-vowel-consonant)
    cvc_vowels = []
    for i in range(1, len(word) - 1):
        if word[i] in vowels and word[i - 1] not in vowels and word[i + 1] not in vowels:
            cvc_vowels.append((i, word[i]))

    if cvc_vowels:
        # Select the rightmost vowel in a CVC sequence
        cvc_vowels.sort(reverse=True)
        return cvc_vowels[0][1]

    # Step 2: If no CVC vowels, find vowels adjacent to at least one consonant
    adjacent_vowels = []
    for i in range(len(word)):
        if word[i] in vowels:
            left_consonant = (i > 0 and word[i - 1] not in vowels)
            right_consonant = (i < len(word) - 1 and word[i + 1] not in vowels)
            if left_consonant or right_consonant:
                adjacent_vowels.append((i, word[i]))

    if adjacent_vowels:
        # Select the rightmost vowel adjacent to a consonant
        adjacent_vowels.sort(reverse=True)
        return adjacent_vowels[0][1]

    # If no such vowels found, return an empty string
    return ''

