def prime_length(string):
    """Enhanced function that returns the sum of:
    - 1 if the string length is a prime number, otherwise 0
    - the median of the ASCII values of characters if length is prime
    - otherwise, returns the factorial of the length modulo 10**9+7

    This combines the prime check with median calculation and a factorial fallback.
    """

    MOD = 10**9 + 7

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def median(lst):
        sorted_lst = sorted(lst)
        n = len(sorted_lst)
        mid = n // 2
        if n % 2 == 1:
            return sorted_lst[mid]
        return (sorted_lst[mid - 1] + sorted_lst[mid]) / 2.0

    def factorial_mod(n):
        result = 1
        for i in range(2, n + 1):
            result = (result * i) % MOD
        return result

    length = len(string)

    if is_prime(length):
        ascii_vals = [ord(c) for c in string]
        med = median(ascii_vals)
        return 1 + med  # prime flag + median of ASCII values
    else:
        return factorial_mod(length)


# Usage
