#print(prime_length('abcdcba'))  # prime length 7: returns 1 + median(ASCII)
#print(prime_length('kittens'))  # prime length 7: same
#print(prime_length('orange'))   # length 6 not prime: returns 6! % MOD
#print(prime_length(''))         # length 0 not prime: returns 0! % MOD = 1

